/* @lc app=leetcode id=2002 lang=kotlin */ class Solution { fun maxProduct(s: String): Int = (1 shl s.length).let { n -> IntArray(n) { m -> (0 until s.length).filter { (m shr it) and 1 == 1 }.map { s[it] }.let { if (it.isNotEmpty() && it == it.asReversed()) it.size else 0 } }.let { dp -> dp.indices.fold(0) { acc1, i -> if (dp[i] == 0) acc1 else java.lang.Math.max(acc1, dp.indices.fold(0) { acc2, j -> if (i and j == 0) java.lang.Math.max(acc2, dp[i] * dp[j]) else acc2 }) } } } }